P = [
 dict(pmid='43005994', doi='10.1097/ee9.0000000000000538', journal='Environmental epidemiology (Philadelphia, Pa.)', title='California petroleum refinery retirements as a natural experiment to assess effects on adverse birth outcomes.', short='UCLA California four refinery retirements difference-in-differences term LBW SGA births 2008-2022', design='Quasi-experimental (difference-in-differences)', pm='Residential proximity to a retiring petroleum refinery (source proxy; no PM measured)', geo='USA (California)', endpoint='Term low birth weight and small for gestational age', tier='A', basis='Proxy / questionnaire', affil='UCLA Fielding School of Public Health, USA; UCLA Fielding School of Public Health, USA', n='Singleton births 2008-2022 conceived within three years before or after the closure of one of four California refineries; difference-in-differences logistic regression, exposed versus unexposed communities by air district. Most retirements were followed by lower odds of term LBW and SGA; strongest for Alon Bakersfield, tLBW OR 0.68 (0.55-0.83) and SGA OR 0.81 (0.74-0.89). Exposure is proximity, not measured PM or any pollutant, so the result cannot be attributed to particles rather than VOCs, SO2 or concurrent economic change; parallel trends across four distinct regions is an assumption the abstract does not test, and the per-refinery heterogeneity is not summarised. Relevance: indirect - fenceline sensor records before and after a closure would supply the exposure contrast this design lacks.', sub=corpus.REPR),
 dict(pmid='', doi='10.21203/rs.3.rs-11347383/v1', journal='Research Square', title='PM2.5 Concentrations among Rural Biomass-Fuel and Urban Mixed-Fuel Households in Eastern Ethiopia: A Comparative Cross-Sectional Study', short='Haramaya HDSS 923 kitchens PurpleAir II-SD PM2.5 rural biomass 473 vs urban 80 ug/m3 wet-dry season', design='Cross-sectional study', pm='Kitchen PM2.5 by PurpleAir II-SD optical sensors, minute data over 3-5 days per household', geo='Ethiopia (Haramaya)', endpoint='24-h mean kitchen PM2.5 by residence, season and household factors', tier='B', basis='Low-cost sensor / network', affil='Haramaya University, Ethiopia; Haramaya University, Ethiopia', n='Preprint. 923 kitchens (573 rural, 350 urban) in the Haramaya HDSS, eastern Ethiopia, monitored for 3-5 days each with 20 PurpleAir II-SD sensors, January 2023 to December 2024. Mean 24-h PM2.5 was 473 (SD 255) ug/m3 in rural and 80 (92) in urban kitchens, difference 393 ug/m3 (95% CI 370-416). In 96 kitchens measured in both seasons, rural means rose from 343 (dry) to 732 ug/m3 (wet), urban from 47 to 105. All rural homes used open fires. The abstract reports no correction or co-location: uncorrected Plantower readings in dense biomass smoke at high humidity carry large, humidity-dependent bias, which is the same axis as the wet-season contrast. Relevance: direct - the largest low-cost household PM dataset in the Horn of Africa; usable only once a smoke- and RH-specific correction is shown.', sub=corpus.OCC),
 dict(pmid='', doi='10.21203/rs.3.rs-11436369/v1', journal='Research Square', title='An OMOP-Compatible Exposure Infrastructure for GeoAI-Enabled Environmental Health Research: The OHDSI GIS Toolchain', short='Tufts OHDSI GIS toolchain OMOP exposure infrastructure synthetic 40000 persons simulated PM2.5 geocoding error attenuation', design='Statistical methods (simulation + application)', pm='Geospatial exposure linkage to OMOP CDM; simulated PM2.5 effects on a synthetic cohort', geo='USA', endpoint='Recovery of known exposure effects; attenuation under geocoding displacement', tier='C', basis='Model (CTM / LUR / ML)', affil='Tufts Clinical and Translational Science Institute, USA; Tufts CTSI, USA', n='Preprint describing an open-source toolchain that standardises geospatial sources into person-place-time exposure records in the OMOP Common Data Model (FAIR catalogue, GIS vocabulary, local geocoding, geometry-attribute index). Tested on a synthetic cohort of 40,000 persons placed in real US census tracts with eight simulated PM2.5 effects and six nulls: derived exposures matched an independent answer key and known effects were recovered. Displacing residences by empirical geocoding error changed estimates little for smooth regional exposure but attenuated them by up to half for exposures varying over 100 m. Synthetic data test plumbing, not real-world exposure validity. Relevance: direct - quantifies why fine-scale (sensor-resolved) surfaces lose half their signal under ordinary geocoding error.', sub=corpus.EXPO),
 dict(pmid='', doi='10.5194/acp-26-15931-2026', journal='Atmospheric Chemistry and Physics', title='Measurement report: Size-resolved seasonal study of inorganic ions and isotopic carbon signatures of aerosol particles at the Wadden Sea', short='Wadden Sea size-resolved inorganic ions levoglucosan 13C 14C organic carbon ship sulfate continental outflow', design='Source apportionment', pm='Size-resolved impactor samples: inorganic ions, levoglucosan, total carbon, 13C and 14C of OC', geo='Europe (Wadden Sea, Germany/Netherlands)', endpoint='Size-resolved composition and fossil/non-fossil OC by season and wind sector', tier='C', basis='Lab / research instrument', affil='Not stated; University of Groningen, Netherlands', n='Measurement report from a Wadden Sea coastal site: size-resolved samples by season and wind sector analysed for inorganic ions, levoglucosan, total carbon and stable and radiocarbon isotopes of organic carbon at several desorption temperatures. Land-sector samples were dominated by nitrate, ammonium and total carbon, the single sea-sector set by sulfate and total carbon; sulfate reached 0.5 ug/m3 in both, suggesting ship emissions. Fossil OC fractions were highest below 250 nm (traffic combustion), and 13C signatures pointed to SOA in smaller, more volatile carbon and photochemical processing at larger sizes. One sea-sector sample set limits the ship attribution. Relevance: peripheral - background composition for coastal network sites; no sensing content.', sub=corpus.EXPO),
]
